<?php
declare(strict_types=1);require __DIR__.'/../app/Core/bootstrap.php';$pdo=App\Core\Database::connection();$rows=$pdo->query("SELECT id FROM commercial_leads WHERE retention_until IS NOT NULL AND retention_until<NOW() AND anonymized_at IS NULL AND status NOT IN('converted') LIMIT 500")->fetchAll(PDO::FETCH_COLUMN);$q=$pdo->prepare("UPDATE commercial_leads SET name=CONCAT('Lead anonimizado #',id),phone='',email=CONCAT('anon+',id,'@invalid.local'),business_type='Anonimizado',notes=NULL,ip_hash=NULL,consent_user_agent=NULL,do_not_contact=1,anonymized_at=NOW(),updated_at=NOW() WHERE id=:id");$event=$pdo->prepare("INSERT INTO lead_privacy_events(lead_id,action,metadata_json,created_at)VALUES(:id,'anonymized',:m,NOW())");foreach($rows as $id){$q->execute(['id'=>$id]);$event->execute(['id'=>$id,'m'=>json_encode(['reason'=>'retention_expired'])]);}echo date('c').' privacy-retention '.count($rows)." lead(s)\n";
